//! Game-owned portable audio handles. Assets generated by tools/generate_audio.py.
const up = @import("unpolished-peas");
pub const Cue = enum { swing, hit, hurt, heal, reject, bell, menu };
const sources = [_][]const u8{
    @embedFile("assets/audio/swing.wav"),  @embedFile("assets/audio/hit.wav"),
    @embedFile("assets/audio/hurt.wav"),   @embedFile("assets/audio/heal.wav"),
    @embedFile("assets/audio/reject.wav"), @embedFile("assets/audio/bell.wav"),
    @embedFile("assets/audio/menu.wav"),
};
pub const Sound = struct {
    effects: [7]?up.core.Audio.SoundHandle = .{null} ** 7,
    music: ?up.core.Audio.MusicHandle = null,
    pub fn init(s: *Sound, ctx: *up.core.GameContext) void {
        const audio = ctx.audio orelse return;
        for (sources, &s.effects) |bytes, *handle| handle.* = audio.loadWav(bytes) catch null;
        s.music = audio.loadMusic(@embedFile("assets/audio/causeway.wav"), .{ .format = .wav }) catch null;
    }
    pub fn deinit(s: *Sound, ctx: *up.core.GameContext) void {
        if (ctx.audio) |audio| {
            for (s.effects) |handle| if (handle) |h| {
                _ = audio.unloadSound(h);
            };
            if (s.music) |h| {
                _ = audio.unloadMusic(h);
            }
        }
        s.* = .{};
    }
    pub fn play(s: Sound, ctx: *up.core.GameContext, cue: Cue, volume: u8) void {
        if (volume == 0) return;
        const audio = ctx.audio orelse return;
        if (s.effects[@intFromEnum(cue)]) |h| {
            _ = audio.play(h, .{ .volume = @as(f32, @floatFromInt(volume)) / 100 }) catch {};
        }
    }
    pub fn ensureMusic(s: Sound, ctx: *up.core.GameContext, volume: u8) void {
        const audio = ctx.audio orelse return;
        const music = s.music orelse return;
        if (audio.musicState() == .stopped and volume > 0) {
            _ = audio.playMusic(music, .{ .loop = true, .volume = @as(f32, @floatFromInt(volume)) / 100 }) catch {};
        } else {
            _ = audio.setMusicVolume(@as(f32, @floatFromInt(volume)) / 100) catch false;
        }
    }
};
